"""
App bundles: a tar archive (usually .tar.gz) with the files an app is launched from,
a compose file at the root plus optional extra files (configs, scripts, ...).
"""
import os
import shutil
import tarfile
import tempfile
from typing import BinaryIO

# compose file names looked for at the bundle root, in this order
BUNDLE_STACKFILE_NAMES = ["compose.yaml", "compose.yml", "docker-compose.yaml", "docker-compose.yml"]
# generated by AppSpec.compile(); a bundle can't ship them
BUNDLE_RESERVED_NAMES = {"compose.override.yaml", "compose.traefik.yaml"}

MAX_BUNDLE_FILES = 1000
MAX_BUNDLE_SIZE = 200 * 1024 * 1024  # extracted size


class BundleError(ValueError):
    pass


def _is_junk(name: str) -> bool:
    """macOS metadata that archivers add: ._* (AppleDouble), .DS_Store, __MACOSX/."""
    parts = name.replace("\\", "/").split("/")
    return "__MACOSX" in parts or parts[-1] == ".DS_Store" or parts[-1].startswith("._")


def _check_members(tar: tarfile.TarFile) -> list[tarfile.TarInfo]:
    members = [m for m in tar.getmembers() if not _is_junk(m.name)]
    if len(members) > MAX_BUNDLE_FILES:
        raise BundleError(f"Bundle has more than {MAX_BUNDLE_FILES} entries")
    total = 0
    for m in members:
        if not (m.isfile() or m.isdir()):
            raise BundleError(f"Bundle entry '{m.name}' is not a regular file or folder (links aren't allowed)")
        parts = m.name.replace("\\", "/").split("/")
        if m.name.startswith("/") or ".." in parts:
            raise BundleError(f"Bundle entry '{m.name}' points outside the app folder")
        total += m.size
        if total > MAX_BUNDLE_SIZE:
            raise BundleError(f"Bundle is larger than {MAX_BUNDLE_SIZE // (1024 * 1024)} MB extracted")
    return members


def _bundle_root(extract_dir: str) -> str:
    """The folder holding the bundle's files: the archive root, or its only top-level folder."""
    entries = [e for e in os.listdir(extract_dir) if e not in (".", "..")]
    if len(entries) == 1:
        only = os.path.join(extract_dir, entries[0])
        if os.path.isdir(only):
            return only
    return extract_dir


def find_stackfile(root: str) -> str:
    for name in BUNDLE_STACKFILE_NAMES:
        if os.path.isfile(os.path.join(root, name)):
            return name
    raise BundleError(f"Bundle has no compose file at its root ({', '.join(BUNDLE_STACKFILE_NAMES)})")


class ExtractedBundle:
    """A bundle extracted to a temp folder. Use as a context manager; the folder is removed on exit."""

    def __init__(self, fileobj: BinaryIO):
        self._tmp = tempfile.TemporaryDirectory(prefix="mc-bundle-")
        try:
            try:
                tar = tarfile.open(fileobj=fileobj, mode="r:*")
            except (tarfile.TarError, EOFError, OSError) as e:
                raise BundleError(f"Not a tar archive: {e}") from e
            with tar:
                members = _check_members(tar)
                try:
                    # "data" also rejects absolute paths, devices and modes we don't want
                    tar.extractall(self._tmp.name, members=members, filter="data")
                except (tarfile.TarError, EOFError, OSError) as e:
                    raise BundleError(f"Can't extract bundle: {e}") from e
            self.root = _bundle_root(self._tmp.name)
            reserved = sorted(n for n in BUNDLE_RESERVED_NAMES if os.path.exists(os.path.join(self.root, n)))
            if reserved:
                raise BundleError(f"Bundle can't contain {', '.join(reserved)}; mc generates it from the app spec")
            self.stackfile = find_stackfile(self.root)
        except Exception:
            self._tmp.cleanup()
            raise

    def read_stackfile(self) -> str:
        with open(os.path.join(self.root, self.stackfile)) as f:
            return f.read()

    def files(self) -> list[str]:
        """Relative paths of the bundle's files."""
        result = []
        for dirpath, _, filenames in os.walk(self.root):
            for name in filenames:
                result.append(os.path.relpath(os.path.join(dirpath, name), self.root))
        return sorted(result)

    def install(self, app_dir: str) -> None:
        """Copy the bundle's files into the app folder. Files that aren't in the bundle are kept."""
        copies = []
        for dirpath, _, filenames in os.walk(self.root):
            rel = os.path.relpath(dirpath, self.root)
            target_dir = os.path.normpath(os.path.join(app_dir, rel))
            if os.path.islink(target_dir) or (os.path.exists(target_dir) and not os.path.isdir(target_dir)):
                raise BundleError(f"Can't write into '{rel}': it exists in the app folder and isn't a folder")
            for name in filenames:
                target = os.path.join(target_dir, name)
                if os.path.islink(target) or os.path.isdir(target):
                    raise BundleError(f"Can't replace '{os.path.join(rel, name)}' in the app folder")
                copies.append((os.path.join(dirpath, name), target))
        # checked everything first, so a conflict doesn't leave a half-installed bundle
        for src, target in copies:
            os.makedirs(os.path.dirname(target), exist_ok=True)
            shutil.copy2(src, target)

    def __enter__(self) -> "ExtractedBundle":
        return self

    def __exit__(self, *exc) -> None:
        self._tmp.cleanup()
